            <div className="flex items-start justify-between gap-3">
              <h2 className="text-xl font-semibold text-gray-900 truncate">{jar.name}</h2>
              <span className="rounded-full bg-green-50 px-3 py-1 text-xs font-medium text-green-700">Active</span>
            </div>
            <p className="mt-1 text-sm text-gray-400">Started {jar.startedOn}</p>
            <div className="mt-4 h-2 w-full rounded-full bg-gray-200">
              <div
                className="h-2 rounded-full bg-gradient-to-r from-violet-500 to-indigo-500"
                style={{ width: `${Math.min(100, (jar.day / jar.targetDays) * 100)}%` }}
              />
            </div>
            <p className="mt-2 text-sm text-gray-500">Day {jar.day} of {jar.targetDays}</p>
            <div className="mt-4 grid grid-cols-2 gap-2 text-sm">
              <div className="rounded-lg bg-gray-50 px-3 py-2">
                <span className="text-gray-400">Salt</span><br />
                <span className="font-medium">{jar.saltPercent}%</span>
              </div>
              <div className="rounded-lg bg-gray-50 px-3 py-2">
                <span className="text-gray-400">Next burp</span><br />
                <span className="font-medium">{jar.nextBurp}</span>
              </div>
            </div>
            {jar.notes && <p className="mt-4 text-sm italic text-gray-500">{jar.notes}</p>}
          </div>
        ))}
      </div>
      <button
        onClick={onAdd}
        className="fixed bottom-8 right-8 rounded-full bg-gradient-to-r from-violet-600 to-indigo-600 px-6 py-4 font-semibold text-white shadow-2xl transition hover:scale-110"
      >
        + Add New Jar
      </button>
    </div>
  );
}
